<h2>Calculate optical-density dilution</h2><p class="lead">Calculate culture/sample volume and diluent required to reach a target OD at a chosen final volume.</p><div class="notice">The arithmetic is the same proportional dilution relationship as C1V1=C2V2, but optical density must be in a validated linear measurement range for that proportional assumption to hold.</div><div class="form-grid"><div class="field"><label for="od1">Measured starting OD</label><input id="od1" type="number" value="1.2" min="0.000001" step="any"></div><div class="field"><label for="od2">Target OD</label><input id="od2" type="number" value="0.1" min="0" step="any"></div><div class="field"><label for="v2">Desired final volume (mL)</label><input id="v2" type="number" value="10" min="0.000001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Starting sample volume</span><strong id="sample">—</strong></div><div class="metric"><span>Diluent volume</span><strong id="diluent">—</strong></div><div class="metric"><span>Dilution factor</span><strong id="factor">—</strong></div><div class="metric"><span>Sample fraction</span><strong id="fraction">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('sample').textContent='—';$('diluent').textContent='—';$('factor').textContent='—';$('fraction').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const o1=num('od1'),o2=num('od2'),v=num('v2');if(!(o1>0&&o2>=0&&o2<=o1&&v>0))throw 0;const s=o2*v/o1,d=v-s;$('sample').textContent=fmt(s,6)+' mL';$('diluent').textContent=fmt(d,6)+' mL';$('factor').textContent=o2>0?fmt(o1/o2,4)+'×':'Infinite';$('fraction').textContent=fmt(s/v*100,3)+'%';$('note').textContent='This treats OD as linearly proportional to concentration over the entered range. Verify your instrument/sample linear range; high OD often requires pre-dilution.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
